/* ---------------- Part 2: Question–Response (Q7–31) ---------------- */
const P2 = [
{ n: 7, qs: 'A', rs: 'B', q: "Who's covering the front desk during the night shift?",
r: ['Yes, the desk is by the elevator.', 'Jorge is, until the new hire starts.', 'About eight hours.'], a: 1,
explain: 'Câu hỏi "Who" (ai) → nêu tên người: "Jorge is, until the new hire starts" (anh Jorge, cho đến khi nhân viên mới bắt đầu). "Yes, the desk is by the elevator" trả lời Yes cho câu Wh- và lặp từ "desk". "About eight hours" trả lời thời lượng (How long).' },
{ n: 8, qs: 'B', rs: 'C', q: 'When will the replacement part arrive at the factory?',
r: ['The assembly line is quiet today.', "It's a hydraulic pump.", 'The supplier says Wednesday morning.'], a: 2,
explain: 'Câu hỏi "When" (khi nào) → mốc thời gian: "The supplier says Wednesday morning" (nhà cung cấp nói sáng thứ Tư). "It\'s a hydraulic pump" nói về loại linh kiện (What). "The assembly line is quiet today" chỉ liên tưởng đến nhà máy, không nêu thời gian hàng đến.' },
{ n: 9, qs: 'C', rs: 'A', q: 'Where can I get a copy of my account statement?',
r: ['Any branch can print one for you.', 'Yes, it was a long statement.', 'Every month, I think.'], a: 0,
explain: 'Câu hỏi "Where" (ở đâu) → nêu nơi chốn: "Any branch can print one for you" (chi nhánh nào cũng in được cho bạn). "Yes, it was a long statement" lặp từ "statement" và dùng Yes cho câu Wh-. "Every month, I think" trả lời tần suất (How often).' },
{ n: 10, qs: 'D', rs: 'B', q: 'Why did the shipment go to the wrong warehouse?',
r: ['Around the corner from the port.', 'Someone entered the wrong postal code.', 'It weighs about two tons.'], a: 1,
explain: 'Câu hỏi "Why" (tại sao) → nêu nguyên nhân: "Someone entered the wrong postal code" (có người nhập sai mã bưu chính). "Around the corner from the port" trả lời vị trí (Where). "It weighs about two tons" nói về trọng lượng lô hàng, không giải thích nguyên nhân.' },
{ n: 11, qs: 'A', rs: 'D', q: 'Would you like a window seat or an aisle seat on the tour bus?',
r: ['The bus leaves at noon.', 'Yes, I booked the tour.', 'A window, so I can take photos.'], a: 2,
explain: 'Câu hỏi lựa chọn "A or B?" → chọn một phương án: "A window, so I can take photos" (ghế cạnh cửa sổ để tôi chụp ảnh). "The bus leaves at noon" lặp từ "bus" nhưng nói về giờ khởi hành. "Yes, I booked the tour" trả lời Yes/No cho câu lựa chọn và lặp từ "tour".' },
{ n: 12, qs: 'B', rs: 'A', q: 'How many applicants have we shortlisted for the analyst position?',
r: ['Six so far.', 'By e-mail, I think.', 'The position was posted online.'], a: 0,
explain: '"How many" hỏi số lượng → "Six so far" (đến giờ là sáu người). "By e-mail, I think" trả lời cách thức (How). "The position was posted online" lặp từ "position" và nói về việc đăng tin tuyển dụng, không nêu số ứng viên.' },
{ n: 13, qs: 'C', rs: 'D', q: "Haven't the guests in room 305 checked out yet?",
r: ['Please check the minibar.', 'Not yet. They asked for a late checkout.', 'Room service is on the third floor.'], a: 1,
explain: 'Câu hỏi phủ định "Haven\'t … checked out yet?" (khách phòng 305 chưa trả phòng à?) → "Not yet. They asked for a late checkout" (chưa, họ xin trả phòng muộn). "Please check the minibar" bẫy âm "check" – "checked out". "Room service is on the third floor" lặp liên tưởng "room" và số tầng, không trả lời câu hỏi.' },
{ n: 14, qs: 'D', rs: 'C', q: "I can't log in to the customer database this morning.",
r: ['Most customers pay by card.', 'The log is on the shelf.', "Let me reset your password right now."], a: 2,
explain: 'Câu trần thuật nêu sự cố (không đăng nhập được vào cơ sở dữ liệu khách hàng) → đưa ra hành động hỗ trợ: "Let me reset your password right now" (để tôi đặt lại mật khẩu cho bạn ngay). "Most customers pay by card" lặp từ "customer" nhưng lạc đề. "The log is on the shelf" bẫy âm "log in" – "log" (cuốn sổ ghi chép).' },
{ n: 15, qs: 'A', rs: 'B', q: 'Is the hospital cafeteria open on weekends?',
r: ["Only until two o'clock.", 'The hospital is on Elm Street.', 'Weekends are the busiest.'], a: 0,
explain: 'Câu hỏi Yes/No → trả lời gián tiếp có điều kiện: "Only until two o\'clock" (chỉ đến hai giờ – tức là có mở nhưng giới hạn giờ). "The hospital is on Elm Street" lặp từ "hospital" và nêu địa chỉ. "Weekends are the busiest" lặp từ "weekends" nhưng không nói căng-tin có mở hay không.' },
{ n: 16, qs: 'B', rs: 'D', q: 'Could you forward me the delivery schedule for next week?',
r: ['It was delivered yesterday.', 'Yes, I scheduled a meeting.', "I'll send it over after lunch."], a: 2,
explain: 'Lời nhờ vả "Could you…?" → đồng ý và hẹn thời điểm: "I\'ll send it over after lunch" (tôi sẽ gửi sau bữa trưa). "It was delivered yesterday" lặp gốc từ "delivery" – "delivered" và nói về việc đã qua. "Yes, I scheduled a meeting" bẫy âm "schedule" – "scheduled" và không liên quan đến lịch giao hàng.' },
{ n: 17, qs: 'C', rs: 'A', q: 'Which software update should we install first?',
r: ['Update me on Tuesday.', 'The security patch is more urgent.', 'The printer is upstairs.'], a: 1,
explain: '"Which … should we install first?" (nên cài bản cập nhật nào trước) → chọn một bản: "The security patch is more urgent" (bản vá bảo mật khẩn cấp hơn). "Update me on Tuesday" lặp từ "update" với nghĩa khác (cập nhật tin cho tôi). "The printer is upstairs" liên tưởng đến thiết bị, không trả lời câu hỏi.' },
{ n: 18, qs: 'D', rs: 'B', q: "Why don't we ask the property manager to repaint the lobby?",
r: ['That would make a good first impression.', 'Because the paint is gray.', 'The lobby is on the right.'], a: 0,
explain: '"Why don\'t we…?" là lời ĐỀ NGHỊ (sao ta không nhờ quản lý tòa nhà sơn lại sảnh?) → đồng tình kèm lý do: "That would make a good first impression" (như vậy sẽ tạo ấn tượng ban đầu tốt). "Because the paint is gray" là bẫy trả lời "Why" bằng "Because". "The lobby is on the right" lặp từ "lobby" nhưng nêu vị trí.' },
{ n: 19, qs: 'A', rs: 'C', q: "You've already submitted your expense report, haven't you?",
r: ['The reporter was late.', 'About two hundred dollars.', "Not yet. I'm still collecting receipts."], a: 2,
explain: 'Câu hỏi đuôi "…haven\'t you?" (bạn đã nộp báo cáo chi phí rồi chứ?) → "Not yet. I\'m still collecting receipts" (chưa, tôi vẫn đang gom hóa đơn). "The reporter was late" bẫy âm "report" – "reporter". "About two hundred dollars" trả lời số tiền (How much), không trả lời đã nộp hay chưa.' },
{ n: 20, qs: 'B', rs: 'D', q: 'What time does the night shift start at the plant?',
r: ['At the north plant.', "At ten o'clock sharp.", 'Yes, the shift supervisor.'], a: 1,
explain: '"What time" hỏi giờ → "At ten o\'clock sharp" (đúng mười giờ). "At the north plant" lặp từ "plant" và trả lời địa điểm (Where). "Yes, the shift supervisor" dùng Yes cho câu Wh- và lặp từ "shift".' },
{ n: 21, qs: 'C', rs: 'A', q: 'How do I return an item without a receipt?',
r: ["You can exchange it for store credit.", "It's a cotton shirt.", 'Yes, the receipt printer is broken.'], a: 0,
explain: '"How do I return…?" hỏi cách làm → "You can exchange it for store credit" (bạn có thể đổi lấy tín dụng cửa hàng). "It\'s a cotton shirt" mô tả món hàng, không nói cách đổi trả. "Yes, the receipt printer is broken" dùng Yes cho câu Wh- và lặp từ "receipt".' },
{ n: 22, qs: 'D', rs: 'B', q: "Who should I send the candidate's résumé to?",
r: ['The meeting will resume at three.', 'To the hiring manager, Ms. Ito.', 'It was a strong candidate.'], a: 1,
explain: 'Câu hỏi "Who … send … to?" → nêu người nhận: "To the hiring manager, Ms. Ito" (gửi cho quản lý tuyển dụng, cô Ito). "The meeting will resume at three" bẫy âm "résumé" – "resume" (tiếp tục). "It was a strong candidate" lặp từ "candidate" nhưng không nêu người nhận.' },
{ n: 23, qs: 'A', rs: 'D', q: 'The guest survey results were better than expected.',
r: ["It's expected to rain today.", 'We survey customers every month.', 'The new breakfast menu probably helped.'], a: 2,
explain: 'Câu trần thuật (kết quả khảo sát khách hàng tốt hơn dự kiến) → phản hồi bằng nhận xét hợp lý: "The new breakfast menu probably helped" (có lẽ thực đơn bữa sáng mới đã góp phần). "It\'s expected to rain today" bẫy âm "expected" nhưng nói về thời tiết. "We survey customers every month" lặp từ "survey" và nói về tần suất, không phản hồi kết quả.' },
{ n: 24, qs: 'B', rs: 'C', q: 'Do you know if the bank accepts foreign checks?',
r: ["You'd have to ask at the counter.", "I'll check the balance.", "No, it's a foreign branch."], a: 0,
explain: 'Câu hỏi gián tiếp "Do you know if…?" → người nói không biết và chỉ nơi hỏi: "You\'d have to ask at the counter" (bạn phải hỏi ở quầy). "I\'ll check the balance" bẫy âm "checks" – "check" (kiểm tra). "No, it\'s a foreign branch" lặp từ "foreign" và trả lời sai nội dung.' },
{ n: 25, qs: 'C', rs: 'A', q: 'Should we ship the order by air or by sea?',
r: ['Yes, it shipped on Monday.', 'The ship is very large.', "By air, if it's needed by Friday."], a: 2,
explain: 'Câu hỏi lựa chọn "air or sea" → chọn một: "By air, if it\'s needed by Friday" (đường hàng không nếu cần trước thứ Sáu). "Yes, it shipped on Monday" dùng Yes cho câu lựa chọn và lặp "ship" – "shipped". "The ship is very large" lặp từ "ship" nhưng không chọn phương án nào.' },
{ n: 26, qs: 'D', rs: 'B', q: 'Why is the loading bay closed this morning?',
r: ["It's close to the highway.", 'A crew is repainting the floor lines.', 'About ten thousand units.'], a: 1,
explain: 'Câu hỏi "Why" → nêu lý do: "A crew is repainting the floor lines" (một nhóm thợ đang sơn lại vạch kẻ trên sàn). "It\'s close to the highway" bẫy âm "closed" – "close" (gần). "About ten thousand units" trả lời số lượng (How many).' },
{ n: 27, qs: 'A', rs: 'D', q: "Isn't there a shuttle to the airport from this hotel?",
r: ['Yes, every half hour from the lobby.', 'My flight leaves at six.', 'The airport is very busy today.'], a: 0,
explain: 'Câu hỏi phủ định "Isn\'t there…?" (khách sạn chẳng có xe đưa ra sân bay à?) → "Yes, every half hour from the lobby" (có, cứ nửa tiếng một chuyến từ sảnh). "My flight leaves at six" liên tưởng đến sân bay, không trả lời. "The airport is very busy today" lặp từ "airport" nhưng không nói có xe đưa đón hay không.' },
{ n: 28, qs: 'B', rs: 'C', q: "I'd like to extend my stay by two nights.",
r: ['Two nights ago, I think.', "Let me check what's available.", 'Extended warranties cost extra.'], a: 1,
explain: 'Câu trần thuật dạng yêu cầu (muốn ở thêm hai đêm) → "Let me check what\'s available" (để tôi xem còn phòng không). "Two nights ago, I think" lặp "two nights" nhưng nói về quá khứ. "Extended warranties cost extra" bẫy âm "extend" – "extended" (bảo hành mở rộng).' },
{ n: 29, qs: 'C', rs: 'D', q: "What's the best way to track my parcel?",
r: ["It's a small parcel.", 'Yes, I tracked down the record.', 'Enter the code on our website.'], a: 2,
explain: '"What\'s the best way to…?" hỏi cách thức → "Enter the code on our website" (nhập mã trên trang web của chúng tôi). "It\'s a small parcel" lặp từ "parcel" nhưng mô tả kiện hàng. "Yes, I tracked down the record" dùng Yes cho câu Wh- và lặp từ "track".' },
{ n: 30, qs: 'D', rs: 'A', q: "The warehouse inventory count starts Monday, doesn't it?",
r: ['I thought it was moved to Tuesday.', 'Yes, I counted them twice.', 'In aisle twelve.'], a: 0,
explain: 'Câu hỏi đuôi (đợt kiểm kê kho bắt đầu thứ Hai, đúng không?) → phản hồi gián tiếp, đính chính: "I thought it was moved to Tuesday" (tôi tưởng đã dời sang thứ Ba). "Yes, I counted them twice" lặp "count" – "counted" và nói về việc đã làm. "In aisle twelve" trả lời vị trí (Where).' },
{ n: 31, qs: 'A', rs: 'B', q: 'Would you mind taking my shift on Saturday?',
r: ['The shift key is broken.', 'About eight hours.', "Sorry, I'm visiting my parents that weekend."], a: 2,
explain: 'Lời nhờ vả "Would you mind…?" → từ chối lịch sự kèm lý do: "Sorry, I\'m visiting my parents that weekend" (xin lỗi, cuối tuần đó tôi đi thăm bố mẹ). "The shift key is broken" lặp từ "shift" với nghĩa phím Shift. "About eight hours" trả lời thời lượng ca làm, không đáp lại lời nhờ.' },
];
LV(P2, [13, 19, 24, 27, 30], [7, 8, 9, 10, 11, 16, 20, 26]);
const p2script = [
{ say: g.TQL[1] }, { pause: 3 },
];
P2.forEach(it => {
p2script.push({ say: 'Number ' + it.n + '.' });
p2script.push({ s: it.qs, t: it.q });
g.TQH.p2s(it, p2script);
p2script.push({ pause: 2 });
});

